-- Check current version and amount of active instances of PCSX2, set working RAM region.
local function pcsx2_version_check()

	version_id = nil
	pcsx2_id_ram_start = nil
	error_flag = nil
	local process_found = {}

	for processID, processName in pairs(getProcessList()) do

		if processName == "pcsx2.exe" or processName == "pcsx2-qt.exe" then

			process_found[#process_found + 1] = processName
			process_found[#process_found + 1] = processID

		end

	end

	if process_found[1] ~= nil then -- Check if there's an instance of PCSX2 up.

		if #process_found <= 2 then -- If CE is using AutoAttach then check how many instances of PCSX2 are up.

			if (process_found[2] == getOpenedProcessID()) then -- Check if CE is attached to PCSX2.

				-- Set memory region according to the version of the emulator.
				-- Check if there's a game loaded, too.
				if process_found[1] == "pcsx2.exe" then

					version_id = 1
					pcsx2_id_ram_start = getAddress(0x20000000)

					if readInteger(pcsx2_id_ram_start) == nil then

						error_flag = 3

					end

				elseif process_found[1] == "pcsx2-qt.exe" then

					version_id = 2
					pcsx2_id_ram_start = getAddress(readPointer("pcsx2-qt.EEmem"))

					if readInteger(pcsx2_id_ram_start) == 0 then

						error_flag = 3

					end

				end

			else

				error_flag = 1

			end

		else

			error_flag = 2

		end

	else

		error_flag = 1

	end

	return {version_id, pcsx2_id_ram_start, error_flag}

end

-- Memory scanner
local function memscan_func(scanoption, vartype, roundingtype, input1, input2, startAddress, stopAddress, protectionflags, alignmenttype, alignmentparam, isHexadecimalInput, isNotABinaryString, isunicodescan, iscasesensitive)

	local memory_scan = createMemScan()
	memory_scan.firstScan(scanoption, vartype, roundingtype, input1, input2 ,startAddress ,stopAddress ,protectionflags ,alignmenttype, alignmentparam, isHexadecimalInput, isNotABinaryString, isunicodescan, iscasesensitive)
	memory_scan.waitTillDone()
	local found_list = createFoundList(memory_scan)
	found_list.initialize()
	local address_list = {}

	if (found_list ~= nil) then

		for i = 0, found_list.count - 1 do

			table.insert(address_list, getAddress(found_list[i]))

		end

	end

	found_list.deinitialize()
	found_list.destroy()
	found_list = nil

	return address_list

end

-- Retrieve Table of Contents of a container file.
local function retrieve_toc(base_address)

	local table_name = {}
	local n = readBytes(base_address, 1)

	for i = 1, n do

		table_name[#table_name + 1] = base_address + (readInteger(base_address + (i * 4)))

	end

	return table_name

end

-- "X item exists in Y table" check function
local function value_exists(tab, val)

	for index, value in ipairs(tab) do

		if value == val then

			return true

		end

	end

	return false

end

-- Write new environment values function
function AC5customEnvParam_outSortieCheck(AC5customEnvParam_outSortieCheckTimer)

	-- Run function as long the emulator is up.
	if readInteger(EEMEMver_AC5customEnvParam[2]) ~= nil then

		-- If the players has entered a mission, pause the "out-of-mission" function checker
		-- and proceed to write the custom values.
		if readBytes(EEMEMver_AC5customEnvParam[2] + 0x47B4C4, 1) == 4 then

			AC5customEnvParam_outSortieCheckTimer.Enabled = false

			-- Retrieve current stage ID:
			local stageID = readBytes(EEMEMver_AC5customEnvParam[2] + 0x5C8CBA, 1)

			-- Scan for the file containing the current stage's assets.
			local found_list = memscan_func(soExactValue, vtByteArray, nil, "2? 00 00 00 A0 00 00 00 A0 01 00 00", nil, EEMEMver_AC5customEnvParam[2] + 0x700000, EEMEMver_AC5customEnvParam[2] + 0x1F00000, "", 2, "0", true, nil, nil, nil)

			-- Clear table so the new backup data can be stored.
			for k, v in pairs(AC5customEnvParam_dataList) do AC5customEnvParam_dataList[k] = nil end

			-- For every stage file read and store the addresses of the environment parameters and their original values.
			for i = 1, #found_list do

				local stage_dat_file_toc = retrieve_toc(found_list[i])

				AC5customEnvParam_dataList[#AC5customEnvParam_dataList + 1] = stage_dat_file_toc[19]
				AC5customEnvParam_dataList[#AC5customEnvParam_dataList + 1] = readBytes(stage_dat_file_toc[19], 864, true)

			end

			-- Apply custom environment settings.
			for i = 1, #AC5customEnvParam_dataList // 2 do

				local idx = (i * 2) - 1

				writeBytes(AC5customEnvParam_dataList[idx], AC5customEnvParam_lookUpTable[stageID][i])

				-- Disable some graphic effects if the script detects that the game
				-- is being emulated in deprecated versions of PCSX2 (v1.x and older).
				-- This is due to those versions having emulation issues rendering said effects.
				if EEMEMver_AC5customEnvParam[1] == 1 then

					writeBytes(AC5customEnvParam_dataList[idx], 0x10) -- Disable cloud shadowmap
					writeInteger(AC5customEnvParam_dataList[idx] + 0x1FC, 0x0) -- Set cloud transparency to 0
					writeInteger(AC5customEnvParam_dataList[idx] + 0x200, 0x0) -- Set cloud amount to 0
					writeBytes(AC5customEnvParam_dataList[idx] + 0x300, 0x0) -- Set dynamic shadow flag to 0

				end

			end

			-- Apply custom god-rays parameters on specific stages.
			if value_exists({09, 14, 29, 31, 34, 38, 44, 64, 65}, stageID) then

				writeFloat(EEMEMver_AC5customEnvParam[2] + 0x441E08, AC5customEnvParam_godraysParamlookUpTable[stageID][1])
				writeFloat(EEMEMver_AC5customEnvParam[2] + 0x441E0C, AC5customEnvParam_godraysParamlookUpTable[stageID][2])
				writeFloat(EEMEMver_AC5customEnvParam[2] + 0x441E24, AC5customEnvParam_godraysParamlookUpTable[stageID][3])

			end

			-- "In-mission" checker function.
			function AC5customEnvParam_inSortieCheck(AC5customEnvParam_inSortieCheckTimer)

				-- Run function as long the emulator is up.
				if readInteger(EEMEMver_AC5customEnvParam[2]) ~= nil then

					-- Pause "in-mission" check function, resume "out-of-mission" checker function.
					if readBytes(EEMEMver_AC5customEnvParam[2] + 0x47B4C4, 1) ~= 4 then

						AC5customEnvParam_inSortieCheckTimer.Enabled = false
						AC5customEnvParam_outSortieCheckTimer.Enabled = true

					end

				else

					getAddressList().getMemoryRecordByDescription("Extended modifications").Active = false

				end

			end

			-- Start "in-mission" check function, resume if there's another instance
			-- of the function active and paused.
			if AC5customEnvParam_inSortieCheck_Timer == nil then

				AC5customEnvParam_inSortieCheck_Timer = createTimer()
				AC5customEnvParam_inSortieCheck_Timer.Interval = 500
				AC5customEnvParam_inSortieCheck_Timer.onTimer = AC5customEnvParam_inSortieCheck
				AC5customEnvParam_inSortieCheck_Timer.Enabled = true

			else

				AC5customEnvParam_inSortieCheck_Timer.Enabled = true

			end

		end

	else

		getAddressList().getMemoryRecordByDescription("Extended modifications").Active = false

	end

end

-----------------+
---- [CHECK] ----+
-----------------+
-- Check how many instances of PCSX2 are running, the current version of the emulator and if it has a game loaded.
-- Set the working RAM region ranges based on emulator version.
EEMEMver_AC5customEnvParam = pcsx2_version_check()

if (EEMEMver_AC5customEnvParam[3] == nil) then

	-- Check if the emulator has the right game loaded.
	local SLUS_20851_check = memscan_func(soExactValue, vtByteArray, nil, "80 55 42 00 90 55 42 00 A0 55 42 00 B0 55 42 00", nil, EEMEMver_AC5customEnvParam[2] + 0x300000, EEMEMver_AC5customEnvParam[2] + 0x4000000, "", 2, "0", true, nil, nil, nil)

	if #SLUS_20851_check ~= 0 then

		-- If the [AC5GCT: MISC VFX MODS] cheat is not enabled suggest the user to enable it.
		if readInteger(EEMEMver_AC5customEnvParam[2] + 0x235400) == 1006715520 then

			showMessage("<< You might want to enable the [AC5GCT: MISC VFX MODS] cheat to get the most out of this script. >>")

		end

		-- Proceed with the rest of the script if the previous checks were passed.
		IsAC5customEnvParamEnabled = true

	else

		showMessage("<< This script is not compatible with the game you're currently emulating. >>")

	end

else

	if EEMEMver_AC5customEnvParam[3] == 1 then

		showMessage("<< Attach this table to a running instance of PCSX2 first. >>")

	elseif EEMEMver_AC5customEnvParam[3] == 2 then

		showMessage("<< Multiple instances of PCSX2 were detected. Only one is needed. >>")

	elseif EEMEMver_AC5customEnvParam[3] == 3 then

		showMessage("<< PCSX2 has no ISO file loaded. >>")

	end

end

----------------+
---- [MAIN] ----+
----------------+

if IsAC5customEnvParamEnabled then

	-- Initialize a table to store backup data.
	AC5customEnvParam_dataList = {}

	-- Start "out-of-mission" check function.
	AC5customEnvParam_outSortieCheck_Timer = createTimer()
	AC5customEnvParam_outSortieCheck_Timer.Interval = 500
	AC5customEnvParam_outSortieCheck_Timer.onTimer = AC5customEnvParam_outSortieCheck
	AC5customEnvParam_outSortieCheck_Timer.Enabled = true

end

[DISABLE]

if syntaxcheck then return end

-- Destroy active timer objects, restore modified data and clear flags on script deactivation.
if IsAC5customEnvParamEnabled then

	if AC5customEnvParam_inSortieCheck_Timer ~= nil then

		AC5customEnvParam_inSortieCheck_Timer.destroy()
		AC5customEnvParam_inSortieCheck_Timer = nil

	end

	if AC5customEnvParam_outSortieCheck_Timer ~= nil then

		AC5customEnvParam_outSortieCheck_Timer.destroy()
		AC5customEnvParam_outSortieCheck_Timer = nil

	end

	if readInteger(EEMEMver_AC5customEnvParam[2]) ~= nil then

		if #AC5customEnvParam_dataList ~= 0 or AC5customEnvParam_dataList ~= nil then

			for i = 1, #AC5customEnvParam_dataList, 2 do

				writeBytes(AC5customEnvParam_dataList[i], AC5customEnvParam_dataList[i + 1])

			end

		end

		writeBytes(EEMEMver_AC5customEnvParam[2] + 0x441E08, {0x99, 0x99, 0x19, 0x3F, 0xCC, 0xCC, 0xCC, 0x3E})
		writeBytes(EEMEMver_AC5customEnvParam[2] + 0x441E24, {0x99, 0x99, 0x19, 0x3F})

	end

	AC5customEnvParam_dataList = nil
	IsAC5customEnvParamEnabled = nil

end

EEMEMver_AC5customEnvParam = nil